// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // No need to call adjustAdminAccess for the divergence in balanceOf; the bug is in balanceOf itself.
        // Calling balanceOf(address(0), 0) on the original contract will revert.
        // On the buggy contract it will pass and return 0.
        bool ok = false;
        try c.balanceOf(address(0), 0) {
            ok = true;
        } catch {
            ok = false;
        }
        // The original contract reverts (ok = false), the buggy one returns (ok = true).
        assertTrue(ok == false, "balanceOf on zero address should revert in the original");
    }
}

