pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Grant admin access to this contract so we can create a game item.
        c.adjustAdminAccess(address(this), true);
        // Create a game item (parameters arbitrary, but must be valid).
        c.createGameItem("test", "uri", false, true, 1000, 100, 10);
        // Now call balanceOf with address(0) -- referent returns 0, bug reverts.
        bool ok;
        try c.balanceOf(address(0), 0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "balanceOf with address(0) should not revert");
    }
}

