contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Create a game item (tokenId 0) with transferable = true so we can later check balance
        c.createGameItem("sword", "ipfs://test", false, true, 0, 0, 100);
        // Mint tokenId 0 with quantity 5 to address(this)
        // First set up the Neuron contract mock by instantiating it with a dummy address to bypass neuron checks.
        // Since the mint function calls _neuronInstance.balanceOf and approveSpender, we need a Neuron mock.
        // For a concrete test, we deploy a minimal mock that returns a large balance and approve works.
        // However, to keep it self-contained, we'll use a different approach: directly use the external burn function to check balance after mint.
        // But the simplest is to use the public balanceOf after a mint.
        // Since we cannot deploy another contract, we can call c.mint() but it requires Neuron.
        // Alternative: we test balanceOf on an address that has never received tokens, where reference returns 0 and bug returns 42.
        // That is a clean divergence: for an address with no tokens, P.balanceOf returns 0, M.balanceOf returns 42.
        // We choose account = address(0x123), id = 0.
        address user = address(0x123);
        uint256 tokenId = 0;
        // Ensure that user has no balance for tokenId (no minting needed).
        // In reference, balanceOf(user, tokenId) returns 0; in bug it returns 42.
