        uint256[] memory ids = new uint256[](2);
        ids[0] = 1;
        ids[1] = 2;

        uint256[] memory balances = c.balanceOfBatch(accounts, ids);
        // Reference returns [1,1], mutant returns [0,0]
        assertTrue(balances[0] == 1 && balances[1] == 1);
    }
}

